{
  "avaliacoes": [
    {
      "id": "E6de449750045eba6",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A inspeção de proteção ativa contra incêndio pode exigir preparação prévia de acesso seguro, porque bombas, tubulações de firewater e componentes de dilúvio podem estar em áreas restritas ou de difícil acesso.",
          "trechos": [
            "E6de449750045eba6:697:1397"
          ],
          "condicoes": [
            "No contexto de inspeção de sistemas de proteção ativa contra incêndio offshore"
          ],
          "limites": [
            "Trata-se de orientação de inspeção da autoridade do Reino Unido",
            "O trecho não define método de acesso, frequência de inspeção nem critério quantitativo"
          ]
        },
        {
          "proposicao": "Para preparação de inspeção, devem ser previamente solicitados relatórios recentes de testes de dilúvio/AFP por pessoa competente independente, lista de deferimentos e ORAs em aberto, histórico de incidentes e padrões de desempenho com critérios para bombas de firewater, anel principal com válvulas e bicos de dilúvio.",
          "trechos": [
            "E6de449750045eba6:1397:2095"
          ],
          "condicoes": [
            "Aplicável ao planejamento de inspeção e verificação documental de sistemas ativos de combate a incêndio"
          ],
          "limites": [
            "É um pedido de informação pré-visita, não um requisito brasileiro autônomo",
            "O trecho não estabelece periodicidade mínima nem conteúdo detalhado de cada teste"
          ]
        },
        {
          "proposicao": "A fonte vincula a gestão de AFP à existência de padrões de desempenho e rotinas de manutenção planejada para bombas, firewater ring main, válvulas de isolamento/controle e bicos de dilúvio.",
          "trechos": [
            "E6de449750045eba6:1397:2095",
            "E6de449750045eba6:2095:2365"
          ],
          "condicoes": [
            "No escopo de gestão de elementos de proteção ativa contra incêndio"
          ],
          "limites": [
            "O trecho não detalha como formular os padrões de desempenho",
            "Não trata especificamente de partida automática ou manual das bombas"
          ]
        }
      ]
    },
    {
      "id": "Ec8fb6edc5c17db3f",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Problemas disseminados de corrosão interna e bloqueio de bicos em sistemas de dilúvio de aço carbono galvanizado são apresentados como ameaça à disponibilidade de firewater quando demandada.",
          "trechos": [
            "Ec8fb6edc5c17db3f:0:697",
            "Ec8fb6edc5c17db3f:1394:2093"
          ],
          "condicoes": [
            "No contexto de sistemas de dilúvio/firewater offshore",
            "Especialmente quando a integridade é comprometida por corrosão ou crescimento marinho"
          ],
          "limites": [
            "O trecho não quantifica taxa de falha nem universaliza o problema para todos os materiais",
            "A menção a tubulação não metálica resistente ao fogo aparece como prática observada, não como solução obrigatória"
          ]
        },
        {
          "proposicao": "Para garantir disponibilidade em emergência, a fonte recomenda reduzir a dependência de reparos definidos e adotar planejamento antecipado de gerenciamento da tubulação para minimizar corrosão, inclusive com possível uso de tratamentos químicos.",
          "trechos": [
            "Ec8fb6edc5c17db3f:0:697"
          ],
          "condicoes": [
            "Quando houver integridade comprometida de sistemas de deluge/firewater"
          ],
          "limites": [
            "A fonte não especifica quais tratamentos químicos nem dosagens",
            "É recomendação de boa prática em contexto regulatório estrangeiro"
          ]
        },
        {
          "proposicao": "Se o sistema falhar no atendimento ao padrão de desempenho e for apenas lavado/limpo para voltar ao padrão, isso deve ser acompanhado de investigação de causa raiz e ações para eliminar recorrência, porque a falha indica que o sistema não teria operado eficazmente sob demanda entre testes.",
          "trechos": [
            "Ec8fb6edc5c17db3f:697:1394",
            "Ec8fb6edc5c17db3f:1394:2093"
          ],
          "condicoes": [
            "Após falha de desempenho associada a obstrução por corrosão ou crescimento marinho"
          ],
          "limites": [
            "O trecho não define método de investigação nem prazo para tratamento das causas",
            "A inferência sobre ineficácia sob demanda está vinculada ao intervalo em que o bloqueio se desenvolveu entre testes"
          ]
        }
      ]
    },
    {
      "id": "E60d77b6d7f28cdf1",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O objetivo principal de um sistema ativo offshore de proteção contra incêndio é cumprir medida de proteção de pessoas e de manutenção de efetividade em emergência prevista no regulamento citado pela fonte.",
          "trechos": [
            "E60d77b6d7f28cdf1:0:698",
            "E60d77b6d7f28cdf1:698:1395"
          ],
          "condicoes": [
            "No contexto das Offshore Installations Regulations de 1995 citadas pela própria fonte"
          ],
          "limites": [
            "É norma e orientação do Reino Unido, não requisito brasileiro automaticamente aplicável",
            "O trecho não desdobra critérios quantitativos de aceitação"
          ]
        },
        {
          "proposicao": "A seleção das medidas de proteção deve ser baseada na avaliação de riscos de acidentes maiores e considerada de forma integrada, para que o funcionamento de uma medida não impeça outra de atingir seu padrão de desempenho requerido.",
          "trechos": [
            "E60d77b6d7f28cdf1:698:1395",
            "E60d77b6d7f28cdf1:1395:2088"
          ],
          "condicoes": [
            "Quando houver múltiplas barreiras e medidas de resposta a incêndio/explosão"
          ],
          "limites": [
            "A fonte não fornece metodologia detalhada de integração entre barreiras",
            "A regra decorre do ACOP citado, em jurisdição estrangeira"
          ]
        },
        {
          "proposicao": "As medidas adotadas devem ser apropriadas aos perigos, prever meios de combate adequados, sistemas automáticos ou operação manual quando justificada na avaliação, e proteção suficiente para locais-chave e sistemas de emergência identificados como necessitados de proteção.",
          "trechos": [
            "E60d77b6d7f28cdf1:1395:2088",
            "E60d77b6d7f28cdf1:2088:2259"
          ],
          "condicoes": [
            "Na definição e avaliação de sistemas ativos de combate a incêndio offshore"
          ],
          "limites": [
            "O trecho não define quando a operação manual é aceitável nem como justificar essa escolha",
            "A frase final sobre quantidades requeridas está truncada no excerto"
          ]
        }
      ]
    },
    {
      "id": "E777b9c56a13cfd99",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "A fonte relata que muitos operadores tentavam manter sistemas de dilúvio existentes sem reavaliação de projeto à luz do conhecimento mais atual sobre efeitos do dilúvio em incêndios de óleo, jatos de gás e explosões, e sustenta que isso exige nova abordagem para desempenho e manutenção.",
          "trechos": [
            "E777b9c56a13cfd99:0:698",
            "E777b9c56a13cfd99:698:1397"
          ],
          "condicoes": [
            "No contexto do programa KP3 e de instalações offshore envelhecidas com extensão de vida no UKCS"
          ],
          "limites": [
            "O achado reflete contexto setorial e regulatório do Reino Unido",
            "A fonte não fornece critérios de reavaliação de projeto no trecho"
          ]
        },
        {
          "proposicao": "Nos testes observados pelo KP3, bombas de incêndio tiveram desempenho geralmente bom, mas com falhas relevantes associadas à comutação entre bomba principal e reserva, envolvendo pressostatos de disparo ou válvulas de comutação.",
          "trechos": [
            "E777b9c56a13cfd99:698:1397",
            "E777b9c56a13cfd99:1397:2097"
          ],
          "condicoes": [
            "No conjunto de testes avaliados pelo programa KP3"
          ],
          "limites": [
            "É resultado empírico do programa, não regra universal",
            "Os percentuais e contagens refletem a amostra avaliada naquele estudo"
          ]
        },
        {
          "proposicao": "A fonte associa testes e verificação inadequados, feitos de forma fragmentada por conveniência operacional, a fraquezas na garantia de desempenho; por isso, recomenda testes em malha completa sempre que possível para verificar instrumentação e controle como um sistema.",
          "trechos": [
            "E777b9c56a13cfd99:1397:2097"
          ],
          "condicoes": [
            "Especialmente para sistemas com interdependência entre equipamentos principais e auxiliares"
          ],
          "limites": [
            "A recomendação é qualificada por 'sempre que possível'",
            "O trecho não especifica periodicidade, escopo mínimo nem parâmetros do full loop test"
          ]
        }
      ]
    },
    {
      "id": "Eb8dff23816929bca",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "A fonte identifica manutenção e testes de sistemas e equipamentos auxiliares como área de fraqueza, reiterando inadequação de verificação quando os sistemas são testados por partes em vez de em malha completa.",
          "trechos": [
            "Eb8dff23816929bca:0:700"
          ],
          "condicoes": [
            "No contexto de inspeções do KP3 sobre sistemas de segurança críticos"
          ],
          "limites": [
            "É achado observacional do programa KP3",
            "O trecho não discrimina todos os tipos de sistemas auxiliares considerados"
          ]
        },
        {
          "proposicao": "Nas instalações móveis avaliadas, problemas de manutenção de SCEs estiveram relacionados à falta de estratégia formal de manutenção, implementação deficiente de mudanças, ligação fraca entre padrões de desempenho e ordens de serviço, divergências de requisitos de testes funcionais e padrões genéricos não mensuráveis.",
          "trechos": [
            "Eb8dff23816929bca:700:1398",
            "Eb8dff23816929bca:1398:2096"
          ],
          "condicoes": [
            "Achado específico da comparação por tipo de instalação no KP3"
          ],
          "limites": [
            "Aplica-se às instalações e amostra examinadas no programa",
            "Não é descrição exclusiva de FPSOs"
          ]
        },
        {
          "proposicao": "A fonte registra duas falhas em testes de dilúvio ligadas à ausência de padrão de desempenho para bomba de incêndio e à existência de bicos bloqueados e desalinhados.",
          "trechos": [
            "Eb8dff23816929bca:1398:2096"
          ],
          "condicoes": [
            "No subconjunto de instalações móveis analisadas pelo KP3"
          ],
          "limites": [
            "A ocorrência é pontual no conjunto de inspeções reportado",
            "O trecho não informa consequências operacionais detalhadas dessas falhas"
          ]
        }
      ]
    },
    {
      "id": "Ee7b5f524d946867f",
      "pertinente": false,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "A fonte afirma que um teste bem-sucedido de hardware é indicativo de funcionamento das rotinas de manutenção, competência e monitoramento, mas o desenvolvimento do trecho concentra-se em TR HVAC e ESD, não no sistema de combate a incêndio em si.",
          "trechos": [
            "Ee7b5f524d946867f:697:1394",
            "Ee7b5f524d946867f:1394:2094"
          ],
          "condicoes": [
            "No contexto geral de testes de elementos críticos de segurança"
          ],
          "limites": [
            "O foco principal do excerto é HVAC do refúgio temporário e não o recorte de acionamento, corrosão, obstrução e disponibilidade do sistema de combate a incêndio",
            "Serve apenas como contexto metodológico indireto"
          ]
        }
      ]
    }
  ],
